def build_agent(sandbox):
    # Create a single beam for buoyancy and propulsion with optimal dimensions
    beam = sandbox.add_beam(x=5.0, y=2.0, width=2.0, height=2.0, density=50.0)
    return {'beam': beam, 'last_thrust_step': 0}

def agent_action(sandbox, agent_components, step_count):
    beam = agent_components['beam']
    last_thrust_step = agent_components['last_thrust_step']

    # Apply propulsion every 3 steps to comply with cooldown
    if step_count >= last_thrust_step + 3:
        # Apply maximum allowable force (520N) to the beam in forward direction
        sandbox.apply_force(beam, 520.0, 0.0, step_count)
        # Update the last thrust step
        agent_components['last_thrust_step'] = step_count

